import { EXPORT_COUNTRIES, SUPPLY_CITIES } from "./countriesData";

export interface Specifications {
  // General
  standard?: string;
  sizeRange?: string;
  finishLength?: string;
  availableForms?: string;
  surfaceFinish?: string;

  // Tolerances
  tolerances?: {
    coldDrawnRound?: Array<{ sizeRange: string; permittedVariation: string }>;
    coldDrawnFlatThickness?: Array<{
      sizeRange: string;
      permittedVariation: string;
    }>;
    coldDrawnFlatWidth?: Array<{
      sizeRange: string;
      permittedVariation: string;
    }>;
    coldDrawnSquareHex?: Array<{
      sizeRange: string;
      permittedVariation: string;
    }>;
    turnedRound?: Array<{ sizeRange: string; permittedVariation: string }>;
  };

  // For coils/sheets/plates
  thicknessRange?: string;
  widthRange?: string;
  widthLength?: string;
  thickness?: string;
  width?: string;
  length?: string;
  form?: string;
  hardness?: string;

  // For pipes
  seamlessPipeSize?: string;
  weldedPipeSize?: string;
  efwPipeSize?: string;
  outsideDiameter?: string;
  scheduleRange?: string;
  outsideFinish?: string;
  deliveryCondition?: string;
  dimensionalSpecification?: string;
  manufacturingShapes?: string;
  pipeEnds?: string;
  manufacturingTechniques?: string;

  // For bars/rods
  hardnessTemper?: string;
  formHardness?: string;
  formLength?: string;
  valueAddedServices?: string;
  testCertificate?: string;

  // Gauge Chart - Flexible for any column structure
  gaugeChart?: Array<Record<string, any>>;

  // Hot Rolled / Cold Rolled specific fields
  hotRolled?: {
    thickness?: string;
    width?: string;
    length?: string;
    finish?: string;
    [key: string]: any;
  };
  coldRolled?: {
    thickness?: string;
    width?: string;
    length?: string;
    finish?: string;
    [key: string]: any;
  };

  // Allow any additional fields
  [key: string]: any;
}

// ===== STOCK CATEGORY INTERFACE =====
export interface StockCategory {
  title?: string;
  items?:
    | string[]
    | Array<{
        name: string;
        description?: string;
        image?: string;
        [key: string]: any;
      }>;
  image?: string;
  [key: string]: any;
}

// ===== PRODUCT MATERIAL INTERFACE =====
export interface ProductMaterial {
  // Core fields (required)
  id: number;
  slug: string;
  image: string;
  title: string;
  shortDescription: string;

  // Optional core fields
  materialGroup?: string;
  standards?: string;
  forms?: string;
  application?: string;

  // ASTM Specifications
  astmSpecifications?: Array<{
    standard: string;
    description: string;
  }>;

  // Supply Range
  supplyRange?: Array<{
    description: string;
    wallThickness: string;
    outsideDiameter: string;
  }>;

  // Extended fields for detailed products
  technicalOverview?: string;

  // Flexible gradeDetails - supports multiple structures
  gradeDetails?: {
    standardAustenitic?: Record<string, string>;
    highTemperature?: Record<string, string>;
    specializedCorrosion?: Record<string, string>;
    standardGrades?: Record<string, string>;
    [key: string]: any;
  };

  manufacturingStandards?: {
    specifications?: string;
    forms?: string[];
  };

  // ===== SPECIFICATIONS =====
  specifications?: Specifications;

  // Stock Availability - supports any category structure
  stockAvailability?: {
    hotRolled?: StockCategory[];
    coldRolled?: StockCategory[];
    slitStrip?: StockCategory[];
    [key: string]: any;
  };

  stockCategory?: StockCategory;

  equivalentGrades?: Array<{
    grade: string;
    uns: string;
    wnr?: string;
    werkstoff?: string;
    jis?: string;
    bs?: string;
    gost?: string;
    afnor?: string;
    en?: string;
    enJisAfnor?: string;
    commonName?: string;
    common?: string;
    sis?: string;
    din?: string;
    iso?: string;
    ks?: string;
    or?: string;
    sa?: string;
    sae?: string;
    astm?: string;
    standard?: string;
    uns_no?: string;
    [key: string]: any;
  }>;

  // Flexible chemicalComposition - supports different elements
  chemicalComposition?: Array<{
    grade: string;
    c?: string;
    mn?: string;
    si?: string;
    cr?: string;
    ni?: string;
    mo?: string;
    ti?: string;
    al?: string;
    v?: string;
    fe?: string;
    o?: string;
    other?: string;
    [key: string]: any;
  }>;

  // Flexible mechanicalProperties - supports different fields
  mechanicalProperties?: Array<{
    grade: string;
    tensile?: string;
    yield?: string;
    elongation?: string;
    density?: string;
    meltingPoint?: string;
    hardness?: string;
    [key: string]: any;
  }>;

  // Flexible thicknessAvailability
  thicknessAvailability?: Array<{
    thickness: string;
    availability?: string;
    widthUpTo36?: string;
    widthUpTo48?: string;
    [key: string]: any;
  }>;

  // Flexible weight charts
  weightSizeCharts?: {
    coldRolledDescaled?: Array<{ size: string; weight: string }>;
    finish1D?: Array<{ size: string; weight: string }>;
    [key: string]: any;
  };

  // Flexible weight chart (supports both pipes and coils)
  weightSizeChart?: Array<{
    size?: string;
    kgs_mtr?: string;
    thickness?: string;
    weightPerM2?: string;
    size2000?: string;
    size2500?: string;
    size3000?: string;
    nps?: string;
    od_in?: string;
    od_mm?: string;
    wall_in?: string;
    wall_mm?: string;
    sched?: string;
    kg_mtr?: string;
    lb_ft?: string;
    [key: string]: any;
  }>;

  // Flexible gauge chart
  gaugeChart?: Array<{
    gauge: string;
    inches: string;
    mm: string;
    approxInches?: string;
    nominalDecimal?: string;
    [key: string]: any;
  }>;

  // Flexible specialty weight chart
  specialtyWeightChart?: Array<{
    thickness: string;
    weightPerM2: string;
    size2000: string;
    size2500: string;
    size3000: string;
    [key: string]: any;
  }>;

  // Size and Dimensions (for Titanium Round Bars)
  sizeDimensions?: Array<{
    metric_size?: string;
    diameter_mm?: string;
    us_rods?: string;
    us_diameter_inch?: string;
    japanese_rods?: string;
    japanese_diameter_mm?: string;
    [key: string]: any;
  }>;

  // Price List
  priceList?: Array<{
    description?: string;
    quantity?: string;
    priceInIndia?: string;
    [key: string]: any;
  }>;

  // Flexible thickness tolerance - supports multiple formats
  thicknessTolerance?: Array<{
    thickness?: string;
    widthUpTo36?: string;
    widthUpTo48?: string;
    width?: string;
    thickness_2_5_4_5?: string;
    thickness_6?: string;
    thickness_8?: string;
    thickness_10?: string;
    thickness_12_5?: string;
    thickness_16?: string;
    thickness_20?: string;
    thickness_25?: string;
    thickness_30?: string;
    thickness_gt_30?: string;
    [key: string]: any;
  }>;

  // Price Range
  priceRange?: Array<{
    designation?: string;
    diameter_in?: string;
    designation_a?: string;
    od_mm?: string;
    weight_kg_mtr?: string;
    wall_thk_mm?: string;
    price_inr_mtr?: string;
    price_inr_kg?: string;
    sch_10s?: string;
    schedule?: string;
    [key: string]: any;
  }>;

  // Company Price Lists
  jindalPriceList?: Array<{
    nominalBore_mm: string;
    nominalBore_inch: string;
    od_mm: string;
    sch5s_wt_mm: string;
    sch5s_price_kg: string;
    sch10s_wt_mm: string;
    sch10s_price_kg: string;
    sch40s_wt_mm: string;
    sch40s_price_kg: string;
    [key: string]: any;
  }>;

  tataPriceList?: Array<any>;
  sailPriceList?: Array<any>;

  // Arrays for various lists
  specializedIn?: string[];
  relatedSearches?: string[];
  exportCountries?: string[];
  supplyCities?: string[];

  // For other products that might have different structures
  keyFeatures?: string[];
  features?: string[];
  applications?: string[];

  // Hot Rolled / Cold Rolled specific fields
  hotRolledSheets?: Array<{
    title: string;
    items: string[];
    image?: string;
    [key: string]: any;
  }>;
  coldRolledSheets?: Array<{
    title: string;
    items: string[];
    image?: string;
    [key: string]: any;
  }>;
  hotRolledPlates?: Array<{
    title: string;
    items: string[];
    image?: string;
    [key: string]: any;
  }>;
  coldRolledPlates?: Array<{
    title: string;
    items: string[];
    image?: string;
    [key: string]: any;
  }>;

  // Allows any additional fields
  [key: string]: any;
}

